import json,hashlib,pathlib
B=pathlib.Path('novelty_catalogue_0825'); R=B/'master/fft_research_master_20261009'; A=B/'addendum/new_research_addendum_20261010'
idx=json.load(open(B/'document_claim_index.json')); rows=[]
def evidence(key):
 p=R/key
 if not p.is_file():
  p=A/key
 if not p.is_file():
  p=B/key
 if not p.is_file():
  matches=[d for d in idx if d['sha256'].startswith(key)]
  if len(matches)==1:
   paths=matches[0]['paths']; preferred=[s for s in paths if '/canonical_sources/' in s]
   p=B/min(preferred or paths,key=len)
  else:
   pp=[q for q in B.rglob('*'+key+'*') if q.is_file()]
   if not pp: raise ValueError((key,len(matches)))
   p=min(pp,key=lambda q:len(str(q)))
 raw=p.read_bytes()
 return {'path':str(p.relative_to(B)),'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
def add(i,name,plain,claim,cost,model,status,novelty,limits,refs,prior=[],rank=None,extra=None):
 r={'id':f'ALG-{i:03}','domain':'Algorithms, complexity, and engineering','name':name,'plain_meaning':plain,'exact_claim':claim,'cost_and_charges':cost,'model_and_uniformity':model,'correctness_status':status,'novelty_status':novelty,'limits_and_counterexamples':limits,'provisional_domain_rank':rank,'ranking_rationale': 'Provisional research priority within algorithms only; neither external novelty clearance nor comparison to algebra/structural candidates.' if rank else 'Unranked: supporting, inherited, conditional, known, superseded, or failed route; retained for completeness.','closest_prior_art_urls':prior,'evidence':[evidence(k) for k in refs],'inspection_status':'Read-only reconciliation of exact-hash proof, audit, or source record; no supplied program executed/imported/compiled/AST-parsed. Historical controls are attributed, not fresh reruns.','error_norm_and_probability':'Exact identity/recognition in declared field unless stated otherwise.'}
 if extra:r.update(extra)
 rows.append(r)
field='Exact field arithmetic with supplied suitable primitive roots; exact equality and inversions charged as declared, O(log N)-bit indexing. Root/field discovery, bit complexity, numerical stability and hardware speed are separate unless explicitly proved.'
prony=['https://fftw.org/pruned.html','https://arxiv.org/abs/1706.04520','https://arxiv.org/abs/2107.07347']
qref=['https://arxiv.org/abs/1507.02959']
add(1,'Certified growing-fiber full Fourier transform','Find and verify a small but growing number of modes inside each fiber, then emit the complete transform.','N=2^k>=4, Q=2^floor(k/2), M=N/Q, 1<=b<=M/2. Accept exactly raw inputs (or guarded Green residuals) whose Q strided M-fibers each have <=b modes; locations/amplitudes are not supplied. All N unnormalized outputs on acceptance.','O(N log(b+2)+Q b²) field/word work and O(N) space for acceptance or rejection, with root tables, recurrence/root-grid discovery, complete checks, synthesis and writes. b=polylog N gives O(N log log N); b=N^o(1) gives o(N log N).',field,'Accepted all-size theorem; recovered companion consistent under documented contracts.','Project-relative growing-budget improvement; classical ingredients. External originality unresolved.','Structured family only. Ordinary fallback restores O(N log N) worst case. Green solver requires every local diagonal and closure denominator nonzero, stronger than invertibility alone. Largest independently counted profile: 7,516,160 vs 7,340,032 operations (2.4% more), no measured speed win.',['additions/0155_material_coverage_and_new_results/reviews/review_growing_fiber/source/THEORY.md','additions/0155_material_coverage_and_new_results/reviews/review_growing_fiber/REVIEW.md','additions/0155_material_coverage_and_new_results/reviews/review_growing_fiber_companion/REVIEW.md'],prony,1)
add(2,'Aggregate-budget fiber recognition','Allow a few completely dense fibers while bounding the total intermediate support.','Accept exactly sum_t r_t<=K0. Light-recognizer failure certifies r_t>B and triggers a paid full M-transform, B=min(M/2,max(1,ceil(K0/Q)) log2 M).','O(N log(B+2)+QB²+M log M(1+K0/B)+N log(1+K0/M)); O(N) space. K0=O(Q log^c N) gives O_c(N log log N). Final over-budget heavy fiber contributes essential +1.',field,'Accepted; distinct extension, not same as per-fiber cap.','Project-relative growing aggregate improvement, priority unresolved.','Earlier O(N) aggregate algorithm can be better when K0=O(Q). Not all inputs, no free heavy-fiber transforms or future-budget charging.',['additions/0155_material_coverage_and_new_results/reviews/review_growing_fiber/source/THEORY.md','additions/0155_material_coverage_and_new_results/reviews/review_growing_fiber/REVIEW.md'],prony)
add(3,'Unknown common-chirp exact recognition','Recover a shared quadratic phase and sparse linear modes directly from all raw samples.','For supplied prime field F_p, N|(p-1), exact primitive Nth root, r>=1,N>=3r, decide x_j=omega^(a j²) sum_{ell=1}^s c_ell omega^(b_ell j), s<=r, and return all N DFT values on success. Zero signal uses empty representation.','Fixed r: O_r(N). Polynomial Toeplitz eliminant/Horner scan gives O(Nr⁴+r^(2+3log2 3)) additions/multiplications, O(1+r⁴) field inversions and O(N+r⁴) field storage; r=o((log N)^(1/4)) is sub-NlogN on accepted class.',field,'Fixed-r theorem independently accepted; polynomial construction and growing-r corollary separately checked.','Potential focused recognition contribution; phase-eliminant algebra is a cross-reference to algebra worker. External priority unresolved.','Raw verification mandatory; reject outside union, not output arbitrary-input transform. Shipped earlier dispatcher retained factorial eliminant, so growing-r bound is not automatically shipped implementation behavior. No robust floating Prony theorem.',['additions/1906_chirp/chirp_audit/AUDIT_REPORT.md','GROWING_RANK_CHIRP_COROLLARY.md','additions/1906_chirp/eliminant_extension/ELIMINANT_EXTENSION.md'],['https://arxiv.org/abs/1706.04520'],2)
add(4,'Balanced CRT tensor and original fiber recognizers','Certify broader structured dense inputs rather than relying on supplied modal side information.','Bounded-rank balanced CRT tensors and bounded-mode strided fibers yield exact full transforms after raw recognition; supports/cosets, cancellation and field guards retained. Integer-polynomial phases at N=d s² have a specified Q=s fiber recognizer for fixed d.','Standalone balanced branches O((1+r)N) exact arithmetic with separate inversions/O(N) memory. Unified designed dispatcher O(N(1+r_T+r_F+r_C⁴)+r_C^(2+3log2 3)).',field,'Accepted structured statements; proposed improved dispatcher is design rather than uploaded functionality.','Restricted extension; classical tensor/Prony/CRT foundation.','Default N=12 divisor choice misses an eligible alternate Q=2 fiber. Completeness of one chosen recognizer is not coverage of every possible split. Fixed-rank and growing-r ledgers differ.',['additions/1954/INTEGRATED_RESULTS.md','additions/1954/tensor_audit/AUDIT_REPORT.md','additions/1954/tensor_audit/EXTENSION_AND_FUSION.md'],prony)
add(5,'Graph-union structured convolution and low-rank escape','Share matched intermediate mode labels across two inputs; allow low rank even when the number of active states is large.','For validated sparse Fourier fibers, matched-label convolution has negative carry phase and factor M. Fixed mode bounds, Q²=O(N) and S<=CQ give linear output work; independent merged-coefficient-rank-d fallback extends state-budget family.','O(N) for fixed structural parameters, including input certification, event charge E and all outputs. S<=min(N,E,sqrt(QKxKy)); H<=min(Kx,Ky,M) controls dQH+dMH.',field,'Accepted, including rank-one family violating every fixed state-budget threshold.','Useful project-relative strict class extension; priority unresolved.','Cancellation/revival can have E>>S; certificate-only public helpers trust input. Rank fallback was independently designed, not attributed to uploaded implementation. No unrestricted convolution/integer-product improvement.',['additions/1954/INTEGRATED_RESULTS.md','additions/1954/graph_audit/GRAPH_UNION_AUDIT_AND_RANK_FUSION.md'],prony)
add(6,'Shear, Newton, orbit-union and confluent recognition','Discover several compatible structured components and sparse innovations, including repeated poles.','Unknown shear/scale Newton recognition, fixed exact-g orbit union via channel traces, and Green sparse innovations are sound after full validation. Confluent extension recovers fixed total order D with a clean nondegenerate 2D-row pilot.','O_D(N) under balance Q²,M²=O(N), total event budget O(Q), suitable p=N^O(1). Pilot transforms, failed candidates, Hankel solves, inversions and writes charged; growing g retains 2^g N.',field,'Accepted under explicit pilot/identifiability promises; confluent bridge is design with controls.','Restricted algorithm extension, external comparison incomplete.','Exact-g is not at-most-g. Repeated shifts, zero component spectra and dirty/degenerate pilots can reject legitimate wider families. Shipped dispatcher does not call all new branches.',['additions/2115/INTEGRATED_RESULTS.md','additions/2115/shear_trace/audit/AUDIT_REPORT.md','additions/2115/shear_trace/audit/CONFLUENT_FUSION.md'],prony)
add(7,'Raw sparse global-phase support recognition','Find a common small set of phase channels without receiving that support as advice.','For Q=KM even,K>=M>=2, fixed unit chirp/shift and supplied compatible roots, discover active phase support r; exactly validate raw input and emit all Q Fourier outputs.','Accepted O(Q+rQ+rK log K+(r+1)M log M); rejection at cap R O(Q+RQ+(R+1)M log M); O(Q) space. M=Theta(log Q) gives O((r+1)Q).',field,'Accepted structured path with full checks.','Distinct restricted class from fiber/Hankel promises; novelty unresolved.','Eligible factorization, roots, chirp choice and inversion must be charged. No arbitrary-length free padding; fixed support can still have maximal ordinary Hankel rank.',['additions/2115/INTEGRATED_RESULTS.md','additions/2115/sparse_phase/audit/PHASE6_SPARSE_SUPPORT_AUDIT.md'],prony)
add(8,'Blind sparse inverse discovery','Recover an unknown short circular inverse filter before computing the full Fourier output.','If an unknown circular polynomial C with <=s taps satisfies C(S)r=e0, recover C, check every cyclic equation and compute every Fourier value; 1<=s<=N/2. Unknown fixed-binomial products driven by one impulse are included without factorization.','O(Ns+s³) field work: 2s paid Fourier probes, recurrence, all-node evaluation, interpolation and full certificate.',field,'Accepted Phase19 advance; stored controls include exhaustive GF(17)^4.','Potential structured-recognition lemma; Prony/annihilating filters classical.','Delay orientation is not unique. Rejection fallback needs compatible root/backend. Source operation proxies omit projective subtractions and scans; fixed caps essential for all-input worst-case envelope.',['additions/2333_source_reviews/INTEGRATED_RESULTS.md'],prony)
add(9,'Unknown shifted two-defect recognition','Use eight probes plus algebraic elimination and full checking for a larger sparse-defect family.','Certain unknown shifted two-defect models are recovered under nonzero resultant, linear specialized gcd and all-sample defect certificate; resultant degree <=45.','O(N) for fixed model degree/caps, including probes and verification under correct guards.',field,'Theorem conditional on nondegeneracy; actual source overly rejects valid noncoprime cases.','Restricted extension; priority not evaluated.','True resonance is alpha^(N/gcd(N,delta))=1, not alpha^N=1. Corrected N8/GF97 counterexample accepted independently; source remains unchanged. Hybrid needs N>=8; proxies omit root rebuilding.',['additions/2351_constructive_gates/INTEGRATED_RESULTS.md'],prony)
add(10,'First-order q-linear cold evaluator','Discover a first-order variable-coefficient recurrence and use the original input to resolve singular cases.','Dyadic N>=4; accept exactly existence of a nonzero (p0,p1,r0,r1) with (p0+p1 q^i)x_i+(r0+r1 q^i)x_(i+1)=0 for all i<N-1. All N exact Fourier outputs; singular target nullity <=1 resolved by paid input-coordinate constraint.','O(N) field/word work and O(N) storage including four-column relation discovery, residual boundary, roots, singular solve and writes.',field,'Accepted identities and restricted all-input recognizer.','Useful coherent algorithm; q-difference/Fourier intertwining ingredients classical. Novelty unresolved.','Not generic dense inputs; exact zero tests are essential; no universal numerical recognition or bit bound.',['952f1d290c9b7105','7ce2a4690ba68ede'],qref,5)
add(11,'Cold sparse recurrence-defect discovery','Find a shift that makes a residual sparse, including zero and singular shifts.','For declared E/J intertwining, accept sparse input <=2s or existence of lambda with <=s residual coordinates. Exact majority ratio discovery plus all-coordinate residual check; later direct recurrence removes lambda=0 and lambda^N=1 exclusions.','O(N(s+1)) work/O(N) space; O(N) decline. Zero target scan 4N−3 field ops; nonsingular nonzero branch 13N−5 before residual synthesis.',field,'Accepted extended theorem; earlier detector is retained as superseded restricted scope.','Structured fast path based on classical majority/recurrence identities.','No acceleration for arbitrary dense residual; sparse contribution cost paid. Singular case needs actual input side information and correct eigenindex.',['5a1a90472e166176','6327eecfbf3a796a','81e45277c8b66bd3','4bc10d7fc62da781'],qref)
add(12,'Galois-defect and conductor hybrid evaluator','Exploit sparse differences along coefficient permutations without pretending field automorphisms are free scalar gates.','At each dyadic conductor, form (P5−I) coefficient defect; two explicit anchors and exact orbit recurrences recover odd frequencies, all conductors cover every output once. Choose cheaper local ordinary FFT per conductor.','Total 9N−12+2T+nu field operations, T=sum(q/2)s_q; O(N(S+1)) bounded-defect regime, generic O(N log N)+O(N) overhead. Supplied roots and index products accounted.',field,'Independent review accepts algebra, output coverage and counts.','Restricted adaptive evaluator; not new Galois mathematics.','No implicit automorphism on arbitrary complex input registers; finite-field order test is not enough for general composite rings. Exact recurrence does not imply floating conditioning.',['935ed394798de399'],qref)
add(13,'Raw binary-index tensor certificate and full evaluator','Certify a rank-one tensor directly from input, then reuse suffix products to calculate every Fourier bin.','N=2^d, x_j=c product_l a_l(j_l). Nonzero pivot and bit-neighbor ratios recover factors; complete regeneration ensures exact acceptance.','O(N) field work/space, exactly 6N−7+2d multiplications, 2N−2 additions, one inversion and O(N) other work for nonzero inputs. All roots/outputs charged.',field,'Accepted restricted recognition and evaluation.','Standard tensor/product structure with explicit full certificate; novelty unresolved.','Only d+1 parameters, not generic dense data. Pivot must be a unit in a residue ring; rejection requires paid external fallback.',['a5bbf86f5f9382be','cf54fbd60faec959'],prony)
add(14,'Sparse annihilator-multiple joint decoder','A slightly higher-degree recurrence can be much cheaper than the minimal one when it has fewer taps.','For supplied distinct modal roots z_s and amplitudes a_s, powered-node polynomial R_b(t)=product_{lambda in {z_s^b}}(1−lambda t) yields recurrence f_m=−sum_i r_i f_(m−bi). All N requested exponential-sum values exact.','Paid support discovery/setup, direct prefix through degree M=b d_b, then O(tau N) recurrence work; fixed tau/M-k structure gives linear route; ordinary FFT fallback retains prior support bound.',field,'Accepted support-adaptive algorithm, with historical README hash-binding caveat.','Classical annihilating-polynomial technique; project-specific certified support adaptation.','Roots/amplitudes supplied, no free extraction from numerator. Minimal polynomial degree is not evaluator lower bound. Does not improve arbitrary k-support O(N log k).',['f1b1856375df9240','0df64bd669a94b81'],prony)
add(15,'Ordered noncommuting affine-cycle filter fusion','Several filters together can make a sparse residual even when each single constituent fails.','With supplied invertible chain of d affine-cycle filters, r pooled parameters and verified s-defect final residual, reverse-order target solves compute exact Fx.','(1+r+6d+2s)N+r(log2N+2)+d field ops; full source passes, preparation, closure and all outputs included.',field,'Accepted exact restricted composition.','Project-relative witness enlarges chosen constituent fast paths, not every possible single filter.','Parameters supplied; singular factors rejected. Family dimension <=r+s for specified rational parameterization, so fixed r+s<N cannot cover generic complex inputs.',['837c563f27047531','0d838ebbcc7268a3','9b6d9bfeedec91ed'],qref)
add(16,'Multiple-port feedback and dirty-state coupling edits','Reuse an already available transform graph and update its feedback ports exactly.','Closing edge U Lambda V^T reduces to invertible d×d Schur closure S=I−G Lambda; z_r=w_r+J^r U Lambda S^-1 g. Rank-one coupling change uses rank-one correction and no new T call; arbitrary dirty scratch preserved by explicit circuits.','Charge source T calls, port preparation, small solve, all propagation and output registers; fixed ports can have linear incremental costs.',field,'Accepted graph identities and scoped reversible compiler.','Woodbury/Schur and finite-dimensional algebra known; implementation integration contribution.','No reduction of first arbitrary T/FFT. Singular closure really nonunique and must reject; arbitrary observation functionals are not free.',['322f0d1a5a76019f','33247cdb1153f020','65eaef1e9c9049a5','ebaebdba4b834328'],qref)
add(17,'Linear q-kernel spectrum preparation','Build a fixed convolution kernel’s entire spectrum without its preprocessing FFT.','For supplied primitive 2Nth root eta and q=eta², H(qz)=(1−z)H(z)+z^N/N gives two affine cycles for H(eta^k). All 2N bins generated exactly.','O(N) cold field work/output and O(N) storage; recurrence preparation 5N+log2N−2 multiplications, plus declared additions/subtractions/one constant inverse.',field,'Accepted finite-boundary identity and constructive preparation.','Project-relative setup improvement; q-Pascal/q-calculus foundations known.','Additional 2Nth root is supplied, not extracted free from q. Fresh input still pays ordinary transforms. Boundary term cannot be omitted.',['9c80e17183dc11eb'],qref)
add(18,'High-degree q-Weyl tail fusion','Compute a high-degree but low-rank part cheaply, without confusing it with the whole invertible transform.','One tail route evaluates p(C)H_q(A) via r-coordinate projection in O(Nr+r²); block route evaluates C^(N−r)p(C), deg p<r, rank<=r using projected inverse convolution and shared decoding.','Second route O(N log(r+1)) including cold preparation, O(N) field storage, only length-2r FFTs; dyadic r<=N/2.',field,'Accepted restricted operator actions.','Standard middle-product/Toeplitz reuse on known q-Weyl similarity.','Full H_q(C) not covered. r=N would need another root/backend and costs ordinary FFT order anyway. Input independence of tail action does not make complete Fourier fast.',['e7c06a4bc237a97c','7bb8400c402dc65c','8c14a657058b7678','8c3b40fa499aacd0'],qref)
add(19,'Sparse q-grading and complete decimation evaluator','A legal sparse basis split exists, but its growing filter degree prevents a fast complete transform.','Finite corner retained: C gauges to (I+J)U; anticommuting involution gives off-diagonal split and legal linear first basis change. Correct recursively closed family has growing filter degree.','Complete non-FFT evaluator Theta(N^(1+0.5log2 3))≈N^1.7925, O(N log N) setup and O(N) storage.',field,'Accepted exact construction, failed as sub-NlogN route.','Structured algebra/recursion result, no general originality claim.','Slower than known O(N log N) comparator. Child D2 has three nonzeros/row, so pretending it is same two-sparse family is false.',['239adb59c756af03','f9de1b8b0cb40096','e84fd241ddf5f362'],qref)
add(20,'q-kernel bounded rational-degree obstruction','A few low-degree resolvents cannot represent the full kernel exactly in the same operator.','If H_q(C)=p(C)r(C)^−1, r(0)!=0 and minpoly C=z^N, then deg p+deg r>=N−1, sharp. Applies to products with bounded total rational degree.','Representation theorem only; no scalar time lower bound.',field,'Accepted via nonzero q-factorial Hankel minors and reciprocal case.','Classical Padé/Hankel tools, project-scoped obstruction.','High-degree sparse factors or different noncommuting operators may be cheap; tail fusion is a positive counterexample to degree→time inference.',['added4a0f022537c'],qref)
add(21,'Whole-orbit q-kernel compression and minimum cycle-flow compiler','Compress an existing favorable sequential operator word and retain all correction filters.','product_{a=0}^{b−1}H_q(xi^a z)=H_(q^b)(z^b) mod z^N. For arbitrary listed phase multiplicities, signed cycle flows correct to reference orbit; median circulation minimizes sum|f_e| in that rewrite family.','Orbit action b C(N/b)+O(N) vs b C(N); compiler O(N+b), root preparation and each forward/inverse filter pass charged.',field,'Accepted exact all-input graph rewrite when input word has prescribed structure.','Classical finite q-exponential identity and L1 median optimality.','Fourier factorization does not automatically contain that word. Intervening noncommuting maps, independent inputs or omitted signed corrections invalidate replacement; no universal algorithm.',['e0b4fdd1981b6366','790aea73dfd7d6f1','d866c38fb26c76d9'],qref)
add(22,'Fixed q-Pascal Fourier factorization and cheap recurrences','A reusable kernel factorization organizes the problem but does not erase its application cost.','Finite q-Pascal/q-exponential Fourier factorization, corrected boundary intertwining, sparse forcing, and first-tail layer identities are valid in their stated nilpotent/truncated rings.','Coefficient preparation and selected recurrence actions may be O(N); complete fresh kernel action retains ordinary convolution/FFT or slower explicit evaluator.',field,'Accepted supporting identities; exact boundaries matter.','Known q-calculus/Vandermonde factorization foundation; task-specific specializations not cleared for priority.','A compact polynomial or fixed kernel is not an O(N) application oracle. All changed child actions and terminal decoders remain charged.',['bc62a95e8677464a','4571d3e8e6f06f0d','58001a15deae9625'],qref)
add(23,'Randomized Gaussian-padded all-length approximation','Approximate every Fourier bin at a coarse input-energy-scaled tolerance, including prime lengths.','For fixed 0<alpha<1/2,c>0, each fixed x independent of fresh states, all sufficiently large integer N: ||Xhat−U_N x||inf<=C_alpha N^−alpha||x||2 except probability <=N^−c. Independent real/imag medians use 2h−1 rows, h>(1+c)/(1−2alpha).','O_alpha,c(N log log N) arithmetic/RAM work, O_alpha,c(N) storage including all outputs, rough padding, tables, Green scans, short filter chunks and long K-transform.','Ideal exact complex arithmetic with supplied exact length-dependent Gaussian/phase/root base constants and normalizers. O(log N)-bit integer work. Bounded fair-bit rejection repair charges every trial and adds exp(−Omega(log²N)) abort.','Independent theorem audit supports asymptotics; number theory unconditional. Finite-word implementation not certified.','Candidate mechanism/all-length accounting, not novel approximation headline on dyadic lengths: HIKP 2012 already implies O(N) dense output at this weak scale there. All-length same-model comparison still unresolved.','Tolerance exceeds typical dense-spectrum bin scale by N^(1/2−alpha). No endpoint alpha=1/2, no relative per-bin/l2 approximation. Prototype fixed seed is not fresh randomness; sampler repair is theoretical; overflow/NaN and rounding guards incomplete.',['additions/2020_2027/gaussian_crosscheck/GAUSSIAN_ALL_LENGTH_AUDIT.md','additions/0431_review_and_content_extensions/fusion_phase_source_review_0408/REVIEW_REPORT.md'],['https://people.csail.mit.edu/haitham/Papers/sFFT.pdf','https://arxiv.org/pdf/1909.11123','https://arxiv.org/pdf/1604.00845'],4,{'error_norm_and_probability':'Unitary l∞ additive error C_alpha N^−alpha ||x||2, per fixed input, probability >=1−N^−c, fixed alpha<1/2 and fixed c. Unnormalized error is C_alpha N^(1/2−alpha)||x||2.','novelty_delta':'Potential all-length/implementation-model mechanism only; dyadic headline has a stronger published corollary.','publication_gate':'Consolidate analytic/decoder/sampling proof; full all-length sparse-FFT/NUFFT prior-art comparison; no numerical implementation theorem yet.'})
add(24,'Elementary rough padding and covariance sharpening','Choose a nearly fourfold working length whose short displacements are all invertible.','Prime M=Theta(log N); choose rough cofactor K so Q=MK=4N+N^o(1), gcd(Q,d)=1 for 0<|d|<M. Elementary inclusion–exclusion proves termination; phi(Q)/Q=1−O(1/loglog N) sharpens variance to O(log N/N).','N^o(1) word search, sieve/divisibility charges with O(log N)-bit operands; later full algorithm charges Q=Theta(N).','Unconditional elementary number theory + word RAM, no prime-gap conjecture.','Accepted supporting lemma for Gaussian path.','Application/refinement of standard number theory; no independent priority claim.','Does not produce a faster exact FFT; finite-size threshold and base coefficient model still matter.',['additions/2020_2027/gaussian_crosscheck/GAUSSIAN_ALL_LENGTH_AUDIT.md'],['https://journals.msp.org/mscand/article/view/2667','https://www.numdam.org/item/10.5802/aif.3214.pdf'])
add(25,'Fully charged fixed-error packed approximate outputs','Use sampling and small finite lookup tables to emit every approximate bin in linear word work.','Bounded integer/common-scale complex input, signed mass L=sum(|Re x|+|Im x|), fixed epsilon,c: all N explicit unitary outputs satisfy linfty error<=epsilon L/sqrt N except N^−c. Two-table transpose proof and simpler guarded-addition route are separate valid implementations/designs.','O_epsilon,c,C(N) word time/O(N) words including integer alias sampling, all finite tables, descriptor keys, packed operations, scaling and N writes.','Uniform randomized word RAM, w=K log N bits, polynomially bounded integer/common-scale inputs, fixed accuracy/failure exponent. No arbitrary-real or giant-word oracle.','Constructive proof completed by audit; whole asymptotic evaluator not benchmarked, only components executed historically.','Potential scoped evaluator contribution; sampling/Maurey, lookup/Four-Russians and finite-alphabet methods known. Priority unresolved.','Possibly enormous threshold/constants. Not arbitrary floating exponent range, exact output, per-bin relative error, vanishing epsilon without reanalysis, or stable full FFT.',['6891a88ccd8a8d63','3eaf065bf9e0da2c','e60223800f3c2eef','10b1c62ff6dbeb71'],['https://arxiv.org/abs/1406.2296','https://www.cs.yale.edu/homes/el327/papers/matrixVectorApp.pdf'],None,{'error_norm_and_probability':'Unitary l∞ <=epsilon L/sqrt N with failure <=N^-c for fixed epsilon,c and bounded/common-scale inputs.'})
add(26,'Shrinking-error packed finite-word evaluator','Make the coarse tolerance decrease while keeping fully charged linear-time word evaluation.','Bounded/common-scale inputs, M=sum(|Re x|+|Im x|), fixed c,C,gamma: all N unitary outputs in O(N) word work with error O(loglog N/sqrt(log N))M/sqrt N and failure <=N^-c. Second parameter point has O(N log N/loglog N) work and error O((loglog N)^(3/2)/log N)M/sqrt N.','All table construction N^gamma polylog N=o(N), lane widths/guard bits, sampling, reads and output writes included; O(N) words.','Uniform randomized O(log N)-word RAM; polynomial bounded integer/common-scale input. Arbitrary separate floating exponents require additional proof.','Accepted qualified theorem; full asymptotic evaluator remains design, prototype is toy/components.','Potential first tradeoff/evaluator contribution; second point is dominated on dyadic lengths by sampling plus pruning O(N loglog N). External priority unresolved.','Weak coordinatewise mass scale can permit all-zero answers for diffuse random signs. No vanishing relative l2 error. Saturation lower bound is only this full packed-row evaluator, not all approximation algorithms.',['b9de2b6602d025e0','81a7f7f897f957f1','a0e3977ae295e461','9accbb2afcac597e'],['https://tygert.com/frand.pdf','https://arxiv.org/abs/1406.2296','https://www.cs.yale.edu/homes/el327/papers/matrixVectorApp.pdf'],3,{'error_norm_and_probability':'l∞ error rho M/sqrt N, failure <=N^-c; rho=O(loglog N/sqrt(log N)) for linear word time.'})
add(27,'Sparse time-surrogate sampling and head/tail planning','Sample a sparse surrogate of the input, optionally retain an exact head or periodic median baseline.','Importance/signed-atom sampling yields fixed-input additive Fourier approximation; exact heads reduce residual mass. Deterministic full-prefix and repaired single-selection planners preserve the promised chosen error contract and complete outputs.','Paid O(N) scan/alias or selection setup plus O(N(1+log k)) dyadic support-pruned synthesis for k samples; coalesced support can be <k. Planner/probability accounting not free.','Ideal arithmetic or separately audited bounded-word common-scale simulation; input-adaptive sampling, not input-independent linear estimator.','Base theorem accepted with later planner corrections; stale/cross-input plans are invalid.','Classical sampling, concentration and FFT pruning. Implementation/engineering combination.','Use relative decay assumptions; vanishing multiplier need not give vanishing absolute error. Repeated whole-input selection can lose claimed cost. Planning must bind actual input/tolerance; source code has stale-state hazards.',['917aeb770759da19','172809eb3dfc0558','811ce88b3cc6c255','f023fcf6bd1d270a','d2290213c1db831b','ce3fde23314cebff'],['https://fftw.org/pruned.html','https://arxiv.org/abs/1406.2296'],None,{'error_norm_and_probability':'Typical unitary l∞ error epsilon||x||1/sqrt N (or residual signed mass); k=Theta(epsilon^-2 log(N/delta)), failure delta. Must use actual variant constants.'})
add(28,'Quantized stage-template Fourier tabulation','Reuse the same small DFT table across grouped levels after paid phase modulation.','Exact Cooley–Tukey identity exposes a common K-point template; quantization produces fixed absolute-error approximation to F_N x/N for bounded inputs. Polynomial tables constrain grouped width and do not give exact O(N) arbitrary-complex DFT.','Grouped passes and all phase/quantization/table construction charged; stated weaker finite-precision sub-NlogN route retained, not exact transform.','Dyadic N, |x_i|<=1, bounded fixed-point word input, fixed absolute epsilon on F/N; uniform O(log N)-word RAM.','Exact stage identity and scoped approximate analysis accepted; source tests only finite evidence.','Classical Cooley–Tukey + tabulation; no originality claim.','Exact intermediate alphabet grows. A bottom-leaf-only table leaves Theta(N log(N/K)); polynomial binary tables force K=O(log N).',['8512b7be7d104174','38bfb47a71a1a2af','3ab989d3f16daf63'],['https://arxiv.org/abs/2211.04643','https://fftw.org/pruned.html'],None,{'error_norm_and_probability':'Deterministic fixed absolute max error epsilon for F_N x/N under bounded input; not unitary same-epsilon scale.'})
add(29,'Deterministic energy-pruned transform','Follow only butterfly branches that could contain an above-threshold coefficient.','Ideal unitary DIF traversal returns exact coefficients above epsilon||x||2 and zeros below, i.e. exact hard-thresholded normalized spectrum.','O(N[1+min(log N,log(epsilon^-2))]) including norm scans/comparisons, routing and dense writes.','Dyadic ideal arithmetic, adaptive branch-energy tests.','Accepted approximation theorem. Prototype has unproved finite-precision decisions.','Standard pruning/energy ideas assembled into scoped proof; novelty unresolved.','Coarse scale may output all zeros on diffuse spectra. Naive binary64 norms underflow/overflow; no robust arbitrary-input NumPy advantage established.',['aba79ba13dfbd987','89c6226655a82738','77a7434d2090cc1f'],['https://fftw.org/pruned.html'],None,{'error_norm_and_probability':'Deterministic unitary l∞ <=epsilon||x||2; zeroed output generally approximate, retained bins ideal-exact.'})
add(30,'Strong-scale head/tail pruning counterexample','Improving the norm requirement restores FFT-sized work for a tempting deterministic hybrid.','For N=4^m and equal-magnitude prefix sqrt N support, every head choice forces either tail traversal or declared sparse-head backend to perform >=N log2N/4 butterflies at stronger epsilon||x||1/sqrt N tolerance.','Lower bound on specified radix-two hybrid and all its head sizes; scans/output only add work.','Fixed algorithm architecture, ideal exact arithmetic; not all deterministic approximation algorithms.','Accepted exact algorithm-specific negative result.','Useful falsification, built from standard energy accounting.','Additional phase structure, other backends or altered intermediate representation outside proof. Native instruction counts not inferred.',['d72c0c9a6c465003'],['https://fftw.org/pruned.html'])
add(31,'Affine-chirp sketch exact decoder','Efficiently decode the measurements of a chirp sketch without claiming they equal the full Fourier transform.','N=KM,K<=M: natural affine-slope chirp sketch full-output decoder supports nonunit slopes via gcd-folding and quadratic period reduction; common-slope case factors further.','O(N log(2K)) exact field operations/O(M+K) extra storage; common slope O(N+K log K).',field,'Accepted decoder of sketch, not exact original DFT.','Structured factorization; broad chirp/FFT ideas classical.','Nonunit/gcd and phase period guards matter. Faster common-slope factorization cannot be advertised for arbitrary varying slopes.',['958a37ab8f0db835','0554f98e8eb0cdca','504e7f01540b55df'],['https://fftw.org/pruned.html'])
add(32,'Chirp-sketch collisions and decoder failures','Certain structured sketches lose information even if a powerful nonlinear decoder follows.','For M divisible by4, even K and specified Mth-root quadratic phase with arbitrary integer-polynomial slopes, fixed fully dense equal-magnitude input pair has identical sketches on probability-1/2 event; one must fail with >=1/4 probability at stated strong scale.','Information/representation obstruction, not runtime lower bound.','Specified random structured sketch, decoder sees only measurements, no raw-input side channel.','Accepted exact collision obstruction; 2Mth-root CAZAC phase removes this collision but natural adjoint has separate failure.','Scoped counterexample, no general sparse-FFT exclusion.','Changing measurements or adding raw input leaves model; repaired phase does not validate adjoint decoder.',['504e7f01540b55df','0554f98e8eb0cdca','a247c8cc138b662c'],[],None,{'error_norm_and_probability':'Strong sketch-specific error target; failure >=1/4 for one fixed input, collision event >=1/2. Do not transfer to Gaussian alpha<1/2 theorem.'})
add(33,'Direct composite covariance and false adaptive certificate','The covariance theorem survives, while a dispatcher claims a guarantee for a different aggregation rule than it executes.','Direct composite/least-prime approximation accepted. Refined Q_cov norm is (p−1)/phi(N) when p²|N, otherwise [(p−1)−lambda_min(W_p)/p]/phi(N). Exact N=3 counterexample refutes advertised offset/Bessel dispatcher certificate.','Planner setup N^(1/2+o(1)) word work in proof; numerical proxy incomplete.','Fixed-input ideal arithmetic, actual coordinate median and proper independent sampler assumptions.','Theorem accepted; implementation certificate demonstrably false.','Covariance refinement inherited/constant-level; no new asymptotic frontier.','Quantized three-grid aggregation is not median. Missing deterministic addition error and differing chosen M break guarantee. Prime-square vs semiprime cases must separate; older mask bound may be stronger.',['additions/1954/INTEGRATED_RESULTS.md','additions/1954/divisor_audit/DIVISOR_SPECTRUM_AUDIT.md','additions/1916/COMPOSITE_GREEN_AUDIT.md'],[],None,{'error_norm_and_probability':'Use audited variant-specific covariance and fixed-input guarantees; advertised adaptive execution fails with probability one on exact N=3 example.'})
add(34,'Direct unequal-block all-length recurrence route','An exact algebraic route does not provide a stable fast approximate implementation.','v14 direct unequal-block formulas can be exact in ideal field arithmetic; variance-only direct-prime ledger cannot beat N log N. Stored binary64 rows show six threshold failures.','Growing recurrence/row costs and conditioning charged; no sub-NlogN direct-prime evaluator proved.','Exact identity model separated from NumPy complex128 prototype.','Algebraic scoped statements survive; actual numeric and helper defects recorded.','Failed route to claimed fast/stable output, retained unranked.','Six failures include huge error and infinities; row-count helper for p in[1/4,1/2) overflows before cap because bound does not decay. These failures do not refute Gaussian padded theorem.',['additions/0431_review_and_content_extensions/fusion_phase_source_review_0408/REVIEW_REPORT.md'],[])
add(35,'Complete exact phase-frame collapse','Using all phase rows recovers the full transform, at ordinary FFT cost.','Full M-row frame is exact; normalized synthesis unitary. Shared joint evaluator collapses separate Green scans to inherited mixed-radix Cooley–Tukey.','Separate-row generic O(Q log Q+QM); intended M=O(log Q) gives O(Q log Q). Joint full evaluator O(Q log Q), O(Q) storage.','Supplied roots and exact field/normalized-complex coordinates with actual input normalization.','Accepted known identity, not exact fast upgrade.','Classical/inherited Cooley–Tukey endpoint.','Constant-row approximation cannot become exact by uncharged full frame. Physical block map singular values differ from normalized summary map; no hidden free recovered inputs.',['additions/2044/INTEGRATED_RESULTS.md','additions/0431_review_and_content_extensions/fusion_phase_source_review_0408/REVIEW_REPORT.md'],['https://fftw.org/pruned.html'])
add(36,'Gaussian measurement-rank strong-accuracy barrier','Too few linear measurements per occupied block cannot meet the much stronger error regime.','With input-independent randomness, <M observations per occupied M=Theta(log N) block, no other input information, and rank deficit >=cN/log N, fixed alpha>1/2 weak-input-energy l∞ success is exponentially small on an average Gaussian test.','Information lower bound, not work lower bound.','Measurement-only model; transcript adaptive queries only if same pathwise deficit and no side channel.','Accepted all-size probability proof, scope corrected.','Standard Gaussian posterior/small-ball argument applied to architecture; originality not cleared.','No alpha=1/2 conclusion. Arbitrary rank deficit alone insufficient: random omission of one coordinate is countercontrol. Does not conflict with alpha<1/2 approximation.',['additions/2044/INTEGRATED_RESULTS.md','additions/2044/gaussian_barrier/GAUSSIAN_MEASUREMENT_BARRIER_AUDIT.md'],[],None,{'error_norm_and_probability':'For fixed alpha>1/2 and deficit d>=cN/log N, average success exp(−Omega(N)); alpha<1/2 theorem unaffected.'})
add(37,'Input-independent linear-sketch strong-scale rank barrier','Uniform per-input strong error and high probability force nearly full expected rank for a random linear estimator.','If law of A independent of x and each fixed x succeeds with l∞ error epsilon||x||1/sqrt N and probability >=1−delta, E rank(A)>=N(1−delta)(1−epsilon²). Also extends to all-coordinate-nonzero inputs by limits.','Rank theorem only; no arithmetic-time implication.','Unitary target and input-independent linear estimator; not median/nonlinear or input-dependent sampling.','Accepted scoped barrier.','Classical rank/energy principles; research application.','Does not exclude v4 importance sampling (input dependent) or v6 coordinate median (nonlinear).',['library/RECOVERED_RESEARCH.md'],[],None,{'error_norm_and_probability':'l∞ epsilon||x||1/sqrt N with per-input probability 1−delta; linear estimator law independent of x.'})
add(38,'Residual-certified finite-word Green/median bridge','Use residual scans to certify rounding in a concrete preconditioner and inverse, rather than assume exact coefficients fit a word.','Rounded tridiagonal source solves and rank-two target inverse have a posteriori error bounds; periodic median head is optimal for signed-component L1. Compose with audited shrinking-error decoder under bounded/common-scale input.','Linear word bridge work including roots, residuals and explicit outputs; core decoder schedule is a separate supplied theorem.','Dyadic bounded integer input, O(log N)-bit rounded arithmetic, induced-norm residual inequalities.','Implemented bridge components and compositional theorem accepted; Fourier/decoder in bridge tests are test-only oracles.','Specific representation-gap repair; classical residual analysis/median/Green formulas.','Not end-to-end implemented linear-time FFT, exact output, or practical speed claim. Zero residual after median does not erase source/target rounding errors.',['2c4633dd25bfeb3c','63b0477ba85c5c3e','8c7d4893378af50b'],[],None,{'error_norm_and_probability':'Unnormalized error <=eta M(residual)+source residual allowance+target/rounding allowances, on decoder success event.'})
add(39,'Marked-tree constant-input jets and forbidden-run frontiers','A polynomial source can be compressed cheaply, while its remaining inverse is still uncomputed.','K(z)=sum_{t<n}z^t(A0^t−E) has at most 2N−2 stored coefficients and O(N) construction for constant input. For marker b and depth L, exact frontier is 2^(n−d) A_b(d), d=min(n,b+L).','Constant-input jet O(N); variable-b frontier cost Theta(N min(n+1,2^b)); retained Schur inverse still paid separately.',field,'Accepted scoped jet/frontier theorem.','Useful exact finite-state combinatorics; no external priority clearance.','Recursively produced polynomial right-hand sides require coefficient convolution not charged by constant-input proof. Separate invertibility guards fail: explicit finite-field counterexamples require coupled Schur guard.',['e3cd7602ca18','d9b0c4ac84ad','fd7bebda8cef','61cd7a1f4bbd'])
add(40,'Weighted marker-cut source preparation','Eliminate a nilpotent interior and prepare its retained source without claiming the retained solve is cheap.','Weighted exact finite Schur formula with retained suffix R plus marker-avoiding set A; eliminated block nilpotent of degree n−b.','Declared marker regime prepares source O(N log N/loglog N), O(N loglog N) memory; full inverse and recovery retain Theta(N log N) costs.',field,'Accepted identity/source improvement with unresolved retained solve.','Classical Schur/automaton method, restricted contribution.','No closed faster Fourier recurrence. Cancellation/depathing must count free-boundary source costs rather than assuming independent packet work.',['ae3357205b8a','8bc97582cb93'])
add(41,'Bounded-coefficient exposed-source packet obstruction','The unnormalized packet bundle itself has enough volume growth to require many additions in a bounded-coefficient model.','H*H=U*diag(lambda)U, with lambda=sum_h 2^h indicators. At least N/4096 eigenvalues are >=2^(n−L); augmented Cauchy–Binet yields addition lower bound N/2[(n−L)/4096−log2(e(1+(n+1)/2^b))].','Asymptotically (1/8192−o(1))N log2 N additions in specified source-constrained bounded-coefficient complex circuits.','Complex bounded coefficients; literal source exposure, supplied phases and charged outputs.','Independent audit accepts model-scoped lower bound.','New-to-project certificate assembled from classical volume method; historical novelty unresolved.','Row normalization destroys this determinant witness; arbitrary coefficient gains or different source interfaces escape. Exact alias identities do not causally compute future states.',['f11dd814af83','bf520e2fe8c3'])
add(42,'Normalized packets reduce to selected Fourier outputs','After correct normalization, the remaining task is selected Fourier computation rather than a volume-growth contradiction.','Frontier rows are orthonormal, span frequency set E with |E|>=N/4096; normalized packet↔selected Fourier maps cost O(NL), L=Theta(log N/loglog N). Masks cost O(N); integer-triangular chirp uses only supplied Nth root.','O(NL) reductions; greedy modulation cover uses O(L) calls, not constant. Fixed ancestor recurrence requires N(n−2b−1) operations; simultaneous two-wire unitary circuit needs >=|E|(n−L)/2 gates.','Exact supplied-root field for identities; complex/unitary model separately for entropy gate.','Accepted after independent normalized audit.','Useful model boundary and reduction, no generic circuit lower bound.','No free historical output tape or nonunitary gates in unitary lower bound. Normalized rows have all minors <=1, so earlier determinant proof cannot be reused.',['4cf8e9936c6f','9fce6c41e720'])
add(43,'Selected-convolution structure and local compression gates','The selected bins have a cheap header, but their long block transforms still cost ordinary FFT work.','K=min(n,2L+2b), Q=2^K, B=N/Q; E is union of full contiguous B-blocks. A contained interval makes <=M arbitrary source columns full spark. Fractional shift F_B^-1 D_a F_B is Cauchy with every square minor and inverse entry nonzero.','Header O(QK³)=N^o(1); Q long transforms N(n−K)/2 butterflies plus outer NK/2, still Theta(N log N).','Supplied dyadic roots; exact field with required denominators/nonvanishing guards, complex comparison where specified.','Construction and independent escape audit accepted within stated interfaces.','Representation/rank gates, not operation lower bounds.','Blocks require >=Q channels in stated balanced local model; no short stencil/bounded quasiseparability/single sparse inverse with monomial ends. General Cauchy fast multiplication and changing interfaces remain allowed.',['inherited_context/selected_convolution_construction_0421/SELECTED_CONVOLUTION_CONSTRUCTION.md','source_packages/selected_convolution_escape_0544/RESEARCH_REPORT.md','source_packages/selected_convolution_gate_audit_0553/INDEPENDENT_AUDIT.md'])
add(44,'Shared inverse root packets and routed correction','Root-of-unity branches really share a denominator; route noncommutation produces a paid correction.','r branches (I−a zeta^i P)^−1 share Q=I−a^rP^r. If right routes commute with P^r, numerator columns have support <=r² and flat Fourier equality requires r²>=N; common route plus left diagonals gives r>=N. Rank-K commutator correction obeys 2r²(K+1)²>=N (prime Fourier: (r²+2)(K+1)>=N+1).','O(Nr) branch execution; naive shared numerator O(Nr²). Rank correction does not automatically give fast apply. Rational bit length can grow O(B+rN).',field,'Independent audit supports exact identity and scoped rank/uncertainty gates.','Classical resolvent/root-filter synthesis with project-specific routed boundary.','Some root packet sums collapse to one O(N) stride solve, but not Fourier. Approximation support-t gate is eta sqrt(max(0,1−t/N)), eta=(1−|a|^r)/(1+|a|^r), in operator and normalized Frobenius norms.',['797d92887fac','6f110c9cd459'])
add(45,'Monomial Weyl-interface normal form','A transform that sends both Weyl generators to monomial matrices already hides a block Fourier transform.','HSH^-1 and HDH^-1 monomial implies H=Mout(I_c tensor F_d^−)Min with cd=N; orientation/calibration fixes actual scalar. Associated compatible interfaces obey m dP dQ>=N.','O(N) recovery from supplied action arrays with no discrete logarithm; action discovery and Fourier blocks remain charged.',field,'Accepted classification/constructor with orientation corrections.','Finite Heisenberg representation theory is classical; explicit calibrated compiler is supporting.','Necessary normal form, not unrestricted converse or cheap application. Supplied action arrays are genuine side information.',['e8883d45965f'],['https://arxiv.org/abs/0803.2921','https://arxiv.org/abs/1102.1268'])
add(46,'Metaplectic Bruhat word compiler','Collapse many permitted shear gates into at most one ordinary Fourier gate.','Odd-prime SL2 action: b=0 branch is monomial, otherwise chirp/Fourier/permutation Bruhat form; exact projective scalar recovered. W has unique LUL shear triple (1,−1,1) under this convention.','O(t+N) plus at most one Fourier for t-gate word; original missing t term repaired.',field,'Accepted classical normal form with paid word read and scalar.','Known Weil/Bruhat mathematics; no independent discovery rank.','Does not make the remaining Fourier cheap or show every matrix has this grammar.',['c06d430e4295'],['https://arxiv.org/abs/0803.2921','https://arxiv.org/abs/1102.1268'])
add(47,'Two-line Weyl product and Fourier-hard factor','An apparently simple two-factor decomposition must put Fourier difficulty inside a factor.','Odd prime and independent Weyl directions: dephased tensor has rank one if kappa=0, otherwise N. Successful scalar factors are quadratic chirps and at least one is Fourier-equivalent with O(N) overhead; rational degree p+q>=N−1.','Representation gate only; factor execution not free.',field,'Independent review accepts corrected phase/sign conventions.','Classical chirp/Gauss and tensor-separation tools; project-specific gate.','No general arithmetic lower bound; only specified two-line factors.',['48aa7789ccad'])
add(48,'Bounded-norm and low-rank Green-stage budgets','Fixed-strength scans cannot create Fourier mixing in a constant number of separately executed passes.','Fixed-degree fixed-strength Cayley stages have bounded induced p-norm for some p<2, while ||F||p>=N^(1/p−1/2), forcing Omega(log N) stages. For Green stages kappa1<=7 and B rank-one edits, 7^t(B+1)²>=N.','Factor-count bound; Omega(N log N) only when every full pass separately costs Omega(N).','Complex unitary monomial endpoints; bounded-strength/conditioning restrictions explicit.','Accepted model-specific norm arguments.','Standard induced-norm/low-rank reasoning, useful restricted exclusion.','Growing strength, arbitrary magnitude diagonals, changed primitives or fused execution escape. No universal Fourier lower bound.',['c0f726bac9b5','a225972f7ad1'])
add(49,'Forward and opposite-sign Green-cycle spectral gates','Forward stages need logarithmic depth, while inverse stages create a real all-pass escape with its own scoped limit.','K=(2I−M)(I−M)^−1 with unit weighted full cycle M^N=−I has squared singulars 2+1/(4sin²(theta/2)). Two forward stages impossible scalar-unitary for dyadic N>=8; t forward stages require (4/3)^t>=N/(pi sqrt(5/2)). Opposite-sign scalar-unitary pair for N>=3 is cancellation or explicit all-pass V; ||V||1<2 forces >log_4 N individually unitary pair blocks.','Each explicit all-pass apply 7N−2 operations plus N+1 preparation in canonical cycle; O(N) gauges. Combined 7^s c_N^(2r)(B+1)²>=N.','Complex unit-modulus full cycles; exact arithmetic realization separately.','Accepted classification/spectral argument with N=2 exception.','Supporting scoped classification, not generic lower bound.','Long mixed words need not decompose into locally unitary pairs. Arbitrary gains, global cancellation or fusion beyond grammar not excluded. Literal one fixed commuting operator cannot be flat at any depth; broader phase-rotated case has its separate short-word gate.',['aa82845b36e8','835aed3aa27f','a5c04a070bc6','61e336a53621'])
add(50,'Whole-word rational degree and scan-broadcast gates','Many cheap-looking passes need sufficient total algebraic complexity in a fixed ordering.','Quasiseparable rank h and rational total degree d give rank<=hd, so Fourier monomial-ended representation needs hd>=floor(N²/4)/N. For t invertible one-way scans with arbitrary shuffles and broadcast rank B, (2B+1)2^(t−1)+B>=N; B=0 requires t>=1+ceil(log2 N).','Representation/pass-count results, no automatic scalar-time implication.',field,'Accepted scoped whole-word and routed sequential-state obstructions.','Classical quasiseparable/rank propagation tools; sharper project model boundaries.','Changing geometry/nonlocal auxiliary ports or uncharged retained transcripts escape the rational model. Full-array pass charging required for time conclusions.',['a4dcf5c62223','e97269eb8788'])
add(51,'Adaptive and nonlinear linearization gate','Some nonlinear-looking arithmetic algorithms can be converted to linear circuits, with important domain limits.','Division-free size-s arithmetic circuit computing a linear map over infinite field linearizes with <=3s gates plus <=s constant preparation at zero; rational circuit at a valid basepoint similarly. A finite generic branch can yield a nonuniform linear circuit.','Charge basepoint/path discovery and constant preparation; no free uniform compiler.',field,'Accepted scoped algebraic linearization.','Classical differentiation/linearization principle, not new unrestricted lower bound.','Boolean finite domains have no open-set argument; branch finding or zero denominator cannot be assumed away.',['a2601a42975c'])
add(52,'Boolean spectral completion and joint Galois stability boundaries','Low-degree completion and ill-conditioned spectral recovery cannot be treated as free decoders.','Degree<=2 Boolean completion from a proper Fourier subset is impossible under stated polynomial model; even-bin observations retain 2^(N/2) ambiguity. Higher-degree finite controls include an N=8 cubic recovery, so low-degree failure is not general impossibility. Joint Galois-orbit recovery has an exponential precision/conditioning barrier for the specified binary family.','Decoder arithmetic, spectral measurement error and precision are charged; side-information coefficient-defect algorithms use a different interface.','Boolean finite-domain polynomial model and complex finite-precision measurement model separately.','Accepted scoped algebraic/rank and stability gates; finite examples not asymptotic proof.','Supporting barriers; no universal nonlinear recovery theorem.','Higher-degree/rational decoders, direct raw input, exact integer coefficients or stronger side information remain outside measured-information lower bound.',['282f1c330f664e66','8b25ef43c7ee33d9','dddb9e4c155cc7f3','84a85c85284c'])
add(53,'Learned dense and rational Green-cycle innovations','Learn a short recurrence from a prefix, then verify the entire stream before trusting reuse.','For full-stream order-d promise, 2d<=M, first 2d samples determine recurrence; finite generating sum Q S_M=P+z^M B with degrees below d, with direct repair at <=d denominator roots.','O(dKlogK+R dKlogK+R dN+d²K+dN+N); M=Theta(log N) simplifies to O(RdN+d²K+N), O(N) space.',field,'Accepted promised recurrence synthesis; randomized verification is not deterministic certification.','Classical Prony/rational generating function with paid corrections.','Late impulse can pass prefix; R sampled checks have explicit field failure probability and cannot be called exact deterministic membership. Capacity q^(2d), not a bijection onto all streams. Finite root setup omissions remain implementation caveats.',['1f9dd1faecb9'],prony)
add(54,'Exact binary NTT and affine-alphabet extension','Finite-word field arithmetic and Frobenius symmetry accelerate restricted finite-field transforms.','d=2^r, N=2^d−1, explicit F_(2^d), input affine F2-dimension b: all N cyclic outputs exact in expected O(N(b+1)log(d+2)) word ops, O(N) words. Binary b<=1 gives O(Nloglog N). Arbitrary-length binary carryless convolution O(Lloglog L).','Cold field construction poly(d), 64 positional tables Q^1/4 poly(d), basis/coordinates O(N(b+1)+d²), conversions, root tests and output order paid. Supplied verified root deterministic; generated root Las Vegas defines returned transform.','Address-capable w=Theta(log N) RAM, bounded words/field element. Exact finite fields; no complex FFT/ordinary integer multiplication.','Two independent audits accept theorem with explicit imported Frobenius machinery.','Known-machinery synthesis. Cantor–Kaltofen plus small-ring tabulation gives same carryless convolution order; affine extension is linearity/elimination corollary.','Full output has Theta(Nlog N) bits. No bit-complexity breakthrough; huge constants, no practical win proved; alphabet cardinality alone does not imply logarithmic affine dimension.',['37ba83e95097','21513b4313f1','26d789dd1045'],['https://arxiv.org/pdf/1802.03932','https://www.texmacs.org/joris/ffft/ffft.pdf','https://kaltofen.math.ncsu.edu/bibliography/91/CaKa91.pdf'])
add(55,'Conditional conditioned macro-FFT and mass-contraction compiler','A faster local primitive would compose into faster global execution, but the primitive is an explicit premise.','Transparent macro replay with unitary resets transfers suitable exact sub-NlogN local primitive into stated stable circuit model. Separately, sqrt-size children of total mass rho N and O(N) paid overhead imply O(N) if rho<1, O(Nloglog N) if rho=1, O(N(log N)^log2 rho) for 1<rho<2; rho=2 restores NlogN.','Printer, replay, local roots, branch count, normalization, setup and all output charged. Harmonic rho_h=2(1−1/h) yields NlogN/loglogN only if realizable.','Conditional exact supplied-root arithmetic; numerical stability needs separately bounded intermediates/precision.','Valid conditional composition and recurrence analysis; missing structural compiler remains unproved.','Standard divide-and-conquer/accounting, useful target specification, unranked.','GFC4 Green/four-layer/partial-Fourier bank compiler not constructed. External OpenAI exact-register algorithm is prior work and its own model, not automatically this stable primitive.',['c07cf114f2827288','452f9dcc695764d7','0a87f075dba77def','89b33d4f81a235de','additions/2318_reviewed/review_incoming_2257_routed/THEORY.md'])
add(56,'Fixed-bank transport and active-bank decoding','A selected active bank may already encode complete Fourier batches.','Calibrated exterior Weyl transport gives a unique scalar; for j input interval and q active outputs, ceil(q/j) forward P calls with paid masks/phases recover the full batch. Square m=q and fixed radix m=rq admit extra one-call Fourier reduction.','Every P call, mask, phase, root and output charged. This is an equivalence/hardness reduction, not a fast P construction.',field,'Accepted within stated bank geometry.','Classical Fourier modulation/transport, project-specific interface certificate.','Original odd-k m<q regime is not proved by square/fixed-radix extension. Cannot replace missing first P call by cached data.',['additions/2351_constructive_gates/INTEGRATED_RESULTS.md'])
add(57,'Young-feedback arbitrary-jet obstruction','A separately exposed feedback component is expensive even when its internal trajectories merge.','For b>=7,L=2^(b−1),L+b<=n−b, arbitrary retained coefficient vectors expose independent orthogonal rectangular packet banks with BB*=diag(2^(b+t)); augmented volume gives Omega(N log N) additions.','Matching paid causal upper bound in selected marker regime. Input-independent preparation may be free in this lower bound.','Exact complex binary linear gates with coefficients of modulus <=1; arbitrary independent retained jets and explicit outputs.','Independent audit accepts all-size component theorem.','Volume technique known; project-specific packet identity and sharp interface exclusion.','Original-source-generated jets have only N independent inputs and are not the arbitrary-jet interface. No finite-field, nonlinear, packed-word, unbounded-coefficient or general FFT lower bound.',['0c7ac6b5c481','12b18138bdb5'])
add(58,'Changed bank interface and four-character channel identities','Changing a basis relocates work; four-way channel splitting remains ordinary radix four.','If F=P0 B Q0 and Q=GQ0, new exterior P=P0 B G^-1 B^-1. Constant swaps give explicit rank-one involution gauges. Monomial active clock forces complete affine residue cosets. Four-character Fourier/Green identities split V4 fibers with correct selectors and holonomy.','Full Fourier recurrence 4T(N)+O(N), not sixteen calls and not reduced mass; Green route three signed scans N,N,2N or four N scans. O(N) gauge applies only with paid explicit vectors.',field,'Audits accept identities, finite N=16 zero-mask control and original-orientation distinctions.','Classical character decomposition/rank-one update, supporting exact interface analysis.','Cheap G does not imply cheap bank conjugate. Finite full-bank N=16 construction not scalable solution. Different arbitrary input residues still require separate child applications.',['7f7eecb76c30','bc18b7d9be50','cbf695f72192','e7baea9679e2','301f089da8d5'])
add(59,'Root-exchange CRT bridges and sparse spectral projectors','Dense transfer matrices may still permit cheap low-rank correction near structured masks.','N=2m, t exchanged parity roots: R_A=I−2U_A V_O,R_B=−I+2U_B V_E; shared-basis commutator rank 2min(t,m−t). Spectral projectors P_K commute and rank(P_A−P_B)=|A symmetric-difference B|; periodic comb plus q exceptions applies to all fresh inputs.','Fixed t bridge/reverse O(N) including plan, but full transform still two child FFTs. Fixed comb period d and q exceptions: O((d+q)N) full filtered time-domain output, O(N) storage.',field,'Independent audits accept exact identities and corrected interface meanings.','Classical CRT/Woodbury/projector synthesis, useful scoped executor.','Filtered time-domain vector is not full spectrum. Correction rank does not imply scalar cost lower bound. Binary-mask-only label recovery needs >=log2N masks and explicitly materialized outputs NlogN, not general complexity.',['0e7a30d7f175','3d88c1359700'])
add(60,'Green-union sparse-inverse and low-rank gate','Sequential invertible factors need sufficient support growth or correction rank to equal Fourier.','If F=product(G_i+R_i), every G_i/factor invertible, rankR_i<=r_i and colsp(G_i^-1)<=s_i, put r=sum r_i,s=product s_i: s(r+1)²>=N; complex prime N: (s+1)(r+1)>=N+1.','One-pole s_i<=2 and bounded r_i force logarithmic factors; time lower bound only for separately materialized Theta(N) passes.','Complex Fourier uncertainty; finite-field transfer only where requisite uncertainty theorem holds.','Independent audit accepts theorem; uploaded modulation implementation has repeated-power Theta(Nlog N) flaw, repaired with running table.','Classical uncertainty and telescoping ranks; project-specific architecture gate.','Branch sums, shared evaluators and high-support inverses outside. Dense/full-rank/full-commutator does not establish hardness. Orbit fusion computes a different stride Green operator, not DFT.',['de519608a7ea'],['https://arxiv.org/pdf/math/0308286'])
add(61,'Trace sieve and short-probe sparse-rational recognizer','Reduce candidate-shift search without dropping final exact verification.','Reciprocal resultant U(w)=w^b V(w+w^-1), b=s(s+1)(2s+1)/6. Removing trace2, gcd(V*,D_N−2) constant iff no admissible nonidentity shift. Two overlapping Hankel pencils need exactly 2s+2 probes, not 4s.','Dickson quotient recurrence O(b²log N), candidate half-root scan O(Ndeg G). Probe stream exactly (4s+3)N ops; for fixed s all bounded candidate certificates O_s(N).',field,'Independent audits accept sieve/enumeration and coverage improvement, conditional on inherited nonzero-resultant and Green guards.','Algebraic candidate filtering using classical Dickson/Prony tools, no historical priority.','Vanished probes/resultant and nonlinear gamma gcd can decline valid inputs. Tonelli–Shanks nonresidue and O(log p+v2(p−1)²) cost not free; complete subgroup scan avoids this. Legacy root-table undercharge not on new active path.',['9d758168f13b','1191e0585afa'])
add(62,'Delta-Graph and spectral Newton-union recognition','Dense anchor fibers plus few spectral changes strictly extend sparse-per-fiber inputs.','Selected N=QM, fixed order d: first d fibers arbitrary, sum spectral supports of dth differences <=R. Exact raw recognizer accepts promised inputs and returns all N outputs via finite Newton tails. Complete reset-union repair drops largest B−1 transition support costs.','Recognition/rejection O_d(N+dM²+M(Q−d+R)); synthesis O_d(N+QR); O(R+1) scalar inversions; fixed d,B,R=O(Q) and balanced Q,M gives O(N) field/word work, O(N) space.',field,'Independent audit accepts theorem and independently repaired reset-union completeness.','Strict project-family enlargement; classical finite differences/Prony and summation. Novelty unresolved.','Shipped greedy multi-anchor misses N=16 witness; fixed divisor/order misses other valid splits. Uploaded fused dispatcher never invokes new branches; certificate helpers trust metadata. No generic-input transform theorem.',['9b13cd8d8d85','0937060734bb','8df920202085'],prony)
add(63,'All-parameter nearby-permutation geometric transform','A few changed successor edges allow an exact transform even at singular geometric parameters.','For supplied permutation order and x_order[t]=z^t with s changed successor edges, twisted difference has support <=2s+1 (<=2s at z^N=1). Fourier covariance recovers regular bins and directly computes at most one resonant bin. Woodbury correction determinant is identically one when nonsingular.','O(N(s+1)) additions/multiplications plus one field inversion, O(N) words; permutation validation, roots, input formation and all outputs charged.',field,'Independent positive repair accepted; source nonsingular Woodbury bound becomes O(N(s+1)²+s³).','Classical sparse differences/Woodbury, useful precise singular-case repair.','Uploaded z^N=1 branch excludes valid inputs; unpermuted-character shortcut invalid after arbitrary permutation. Zero-defect source repeated exponentiation is Theta(Nlog N), repaired by hoisting.',['289facfec75c'])
add(64,'Root-free rank-two and real-Fourier Green queries','Recognize short recurrences without factoring their characteristic polynomial.','Every raw vector satisfying a fixed-coefficient recurrence of order <=2 can be recognized and fully transformed in O(N), including repeated and irreducible roots; at most two singular bins computed directly. Original geometric/difference fast path accepts exactly N(N−1)+4 binary words for supported N>=8.','O(N) exact field work/output; supplied root/normalization preparation explicit. Separate supplied r-query execution O(rN), not a universal lower bound.',field,'Independent audit accepts identities and broader root-free recurrence extension.','Classical resolvents/linear recurrences and Hankel counts; restricted exact executor.','Leading Hankel rank alone insufficient; late impulse counterexample. Binary coverage exponentially small. Full recurrence class broader than uploaded distinct split-node detector.',['c074b19dd40f','d32912d6f37d'],['https://arxiv.org/pdf/1011.1760'])
add(65,'Orthogonal-bank projectors and fixed-frame recovery','Exact bank energies certify a proper-subspace transform, while full frames retain FFT-scale work.','P=V(V*V)^-1 V*; ||F x−F P x||²=||x||²−sum b*Gamma^-1 b. Every fixed proper P has worst-case relative l2 error exactly1. Stationary q=M frame is exact all-input factorization; normalized local singulars lie in [1−delta_q,1+delta_q], delta_q=exp(pi(M−1)(q−1)/(2KM))−1.','Fixed proper subspace can be recognized by exact zero residual at its paid evaluator cost; q=M remains FFT-scale including coefficients, short FFT bank and long scans.','Exact complex supplied constants; finite precision requires separation/stability theorem.','Independent audit accepts exact identity, minimax correction and conditioning refinement.','Classical projectors/frames; useful architecture analysis, unranked.','Coordinate leverage sqrt(1−q/M) is not minimax over all inputs. Adaptive sketch-only zero transcript needs >=M rank-N/M observations; direct raw reads outside. No near-subspace numerical membership certificate.',['a313395ea0fe'])
add(66,'Norm-certified finite-word tabulated FFT','Batch many low-precision FFT levels into one paid lookup while preserving full-vector relative accuracy.','Fresh dyadic N, binary complex inputs with O(log N)-bit descriptions and polynomial dynamic range: deterministic explicit y satisfies ||y−U_Nx||2<=epsilon||x||2. Fixed dyadic 0<epsilon<=1/4 or epsilon=2^-ceil((log2N)^beta), fixed0<beta<1: O_epsilon(Nlog N/loglog N) word ops,O(N) words. Efficiently supplied precision p=o(log N) yields o(Nlog N).','All cold padded tables, root/phase approximants, normalization, exact scaling, input/output, packing, guards and addresses paid. Alphabet b=O(p+loglog N), largest dyadic m with mb<=gamma log2N; setup N^gamma polylog N for fixed gamma<1.','Address-capable word RAM w=Theta(log N), integer arithmetic/shifts/division; coefficients use O(log N+p) bits. Finite binary input and efficiently available precision parameter.','New full paper proof survives two independent read-only reviews at fixed epsilon; no supplied code execution. General merely computable precision schedule must be qualified by its computation cost.','Potential substantive normwise finite-word synthesis; standard Four-Russians mechanism. No model-matched priority clearance, and word complexity cannot be compared as scalar arithmetic.','Dyadic only. At polynomially small accuracy block size constant and saving disappears. Prototype high-precision tests generate entries on demand and force inadmissible small-N radices; toy eager tables only, no production benchmark or complete implementation verification.',['library_delta_extracted/fft_norm_certified_tabulation_2026-10-10/fft_norm_tabulation_2026-10-10/THEORY.md','library_delta_extracted/fft_norm_certified_tabulation_2026-10-10/fft_norm_tabulation_2026-10-10/README.md'],['https://arxiv.org/abs/2211.04643'],None,{'error_norm_and_probability':'Deterministic full-vector relative l2 error epsilon||x||2, unitary normalization. No probability of failure; alphabet saturation excluded in theorem, numerical prototype only supporting.','rank_eligible':True,'ranking_rationale':'New material, provisionally eligible only after cross-domain review; strongest algorithm accuracy model here, priority unresolved.'})
add(67,'CRT-15 all-input codelet circuit','A classical coprime split removes some twiddle work and improves lower-order constants.','N=15G,G=2^t over suitable supplied prime field/root: Good–Thomas 15 codelet 81 adds25 multiplies, full A=15Gt+81G,M=(15G/2)t+10G+15. Saves22G−14 field ops versus stated nested Cooley–Tukey. Fourier F_AB monomial-equivalent to F_A tensor F_B iff gcd(A,B)=1 via cross-ratio orders.','Total (45/2)Gt+91G+15, Theta(Nlog N); O(N) lower-order saving. Cold roots/indexing/storage bit charges separate and implementation-specific.','Exact field-operation model counting every nonidentity constant multiplication; supplied prime/root.','New theorem and cost ledger read statically, classical identity consistent; reported tests not rerun.','Known Good–Thomas/codelet engineering and elementary cross-ratio gate; unranked.','No asymptotic improvement. Finite comparisons cannot substitute for generic root availability or bit analysis. OpenAI challenge placeholder is not evidence that its separate solution proof is absent/invalid.',['library_delta_extracted/fft_hero1_phase27_20261010/fft_hero1_phase27/THEOREM.md','library_delta_extracted/fft_hero1_phase27_20261010/fft_hero1_phase27/COST_LEDGER.md'],['https://rss.onlinelibrary.wiley.com/doi/10.1111/j.2517-6161.1958.tb00300.x'])
add(68,'Free-boundary cancellation and marked-cycle unresolved inverse','Exact free-map cancellations leave the original selected Fourier task.','Free outputs have forced contribution equal to cheap correction; sharing cancels it and leaves partial Fourier. Suffix cuts covering all outputs need at least binary-necklace count. Alternative depathing language has O(Nloglog N/log N) retained coordinates but changes retained operator. Stationary Q^n Fourier graph and marked-circuit differentiation reduction exact.','Separate suffix-cut inverse schedules cost >=N(n−b)(n−b+1)/(2b) state visits; b≈2log2n gives Omega(Nn²/log n). Existing complete source/recovery still Theta(Nlog N).',field,'Accepted failed-route/accounting theorem and conditional scalar-circuit reduction.','Classical Schur/path combinatorics; useful route closure, no novelty rank.','No fast marked scalar circuit or new retained inverse supplied. Individual chart pivots may vanish despite full invertibility; z=omega explicit counterexample.',['0104d324f31e','aae67ad1f4d3','8457d31fac18'])
add(69,'Correction-graph rational and multi-parent product reuse','Reuse paid anchors across related queries, including higher differences and both changing operands.','Exact rational intertwining moves a source resolvent query to target scans; fixed-width closure O(N). Product secant A_iB=2A_(i−1)B−A_(i−2)B+R_iB. Varying degree-dA,dB operands requires product degree dA+dB and corresponding seed prefix.','Rational Q-query total O(Nlog N+QN) after paid first anchor; fixed degree product discovery/recurrence O(Qn) digit work plus each seed M(8n), residual n sum s and carries.','Exact field or exact integer digit model, trusted cache and fully verified relationship metadata.','Independent reviews accept after signed-buffer length guard correction.','Known bilinearity/finite differences/Woodbury synthesis; restricted engineering.','Both-affine products require three seeds, not two. Relation discovery and planning paid; corrupt anchor not authenticated by metadata. Scalar scheduler objective not bit-cost optimum.',['86c1119ba0e47','910de7944d36','65eaef1e9c90'])
add(70,'Sparse edits, low-rank batches and persistent convolution','Related signals can share an expensive first transform.','Rank-r M-vector batch costs O(rNlog N+MrN) after paid basis recognition; s supplied sparse edits cost O(sN) full spectral updates. Circular convolution with cached basis cores and both-side sparse changes follows exact bilinear four-term expansion.','Cold base FFTs/cores O(Nlog N), warm one-edit full output Theta(N); M explicit outputs Omega(MN). Dynamic integer bit flip P+=±(B<<t) costs O(n) bit work after paid initial product.','Exact ring identities; numerical NumPy/SciPy engine requires its own error checks. Supplied/verified edits and trusted immutable anchors.','Accepted classical identities; historical performance reports not freshly rerun.','Known reuse and output-optimal special workloads, no discovery rank.','No free basis/rank recognition, input read, cache population, subscriptions, stale keys, memory or first transform. Wrong cross-term omission when both operands change gives incorrect output.',['0bf1ba9d8091','ad60dca00f5e','ce8b2e31e08f'])
add(71,'Cache rewrite engine, real FFT packing and native optimization','Engineering changes reduce repeated or redundant work on suitable workloads.','Ring-valid lazy transform views combine shifts, modulations, sparse edits and linear combinations; selective binary subproblem caching shares exact repeated nodes. Classical two-real-signals packing uses one complex FFT plus O(N) unpacking.','All cache lookups/hash keys, basis plans, root tables, input conversion, memory traffic and full output charged; random binary shared-DAG expected total remains Theta(Nlog N).','Workload-specific machine/word and floating arithmetic, distinct from exact operation theorems.','Known engineering; uploaded tests/benchmarks historical only, no current execution.','Classical FFT packing/caching/vectorization; project integration may be useful without new mathematics.','Two arbitrary complex inputs cannot be injectively linearly packed into one same-sized complex vector. Tuned real FFT baseline may beat packing. Float cancellation, dtype/stride guards, stale plans and empirical crossover must be checked.',['e5e5c4d8a0fae','4bdb965b811b','e00564ed7ae5'],['https://fftw.org/pruned.html'])
add(72,'Structured exact integer products and prime-free backend','Few digit runs or sparse deviations give exact linear-size work; a separate unbounded backend supplies correctness without prime search.','Repeated-digit, sparse-digit, fixed-run and baseline-plus-exception decompositions give O(s(n+m)) digit-kernel work, with every carry. Prime-free dyadic m>=2n−1 uses P=2^t+1>C, t multiple m/2, omega=2^(2t/m); principal-root orthogonality holds even for composite P.','Fixed radix/structure gives linear digit work. General backend O(mtlogm+mM(t)+nK²) bit work, K=O(logn+logbeta), O(mt) bits. Fixed beta t=Theta(n): O(n²logn+nM(n)); schoolbook O(n³).','Exact canonical digits, constructed composite ring, no hidden CRT/primality/root oracle.','Independent reviews accept after input-iterator fix; full field/bit model explicit.','Classical identities and Fermat-ring correctness synthesis; unranked.','Elementary general backend not asymptotically competitive. Coefficient convolution wider than digits. Cached numerical vs coefficient formats have different bit widths; scalar MST not bit-optimal.',['20a1b09d49db','2afbf02d55f2','33cb0a98b211','5618cf3cc85e'])
add(73,'Approximate-to-exact integer rounding gate','A valid error budget can certify rounding, but this particular coarse sampler then loses its saving.','Unitary convolution coefficient error E=epsilon_a La B2+epsilon_b Lb A2+epsilon_a epsilon_b La Lb+epsilon_i(A2+epsilon_a La)(B2+epsilon_b Lb)+rho. Strict E<1/2 implies exact nearest-integer recovery on the simultaneous good event.','All forward/inverse/rescaling/product numerical error in rho; norm computation and carries paid. For any nonempty integer residual tail, this sufficient certificate forces current Hoeffding sampler to exact-input bypass.','Exact integer targets plus explicitly certified numerical errors or probabilistic good events.','Independent review accepts normalization/error derivation and scoped negative bridge; exhausted-iterator bug repaired.','Standard norm/error analysis; no general approximation lower bound.','Monte-Carlo confidence is not verification of this run or Las Vegas correctness. One coefficient error is not repaired by carry. Better correlated errors/modular methods remain possible.',['20a1b09d49db','5618cf3cc85e'],[],None,{'error_norm_and_probability':'Absolute coefficient error <1/2; probabilistic forward/inverse assumptions give failure <=delta_a+delta_b+delta_i, not deterministic certification.'})
add(74,'Synthetic WHT, cancellation search and finite-width controls','Small exact wins and cancellation-aware search are useful controls, not scalable FFT theorems.','Finite topology/cancellation searches and WHT synthetic constructions establish only displayed finite circuits or conditional core savings. Fixed-field WHT acceleration by bit packing is prior art; constant-factor real DFT/WHT arithmetic improvements also published.','Charge entire circuit, paid core, roots and preparation. No extrapolation from finite N or scalar counts to bit/word runtime.','Several distinct finite-field, real scalar and word-RAM models; incomparable without conversion.','Retained finite exact/conditional engineering results; broad novelty not claimed.','Known transform identities/search and published WHT methods.','Conditional saving 4.986133e−5 does not construct missing scalable core. Finite exact-width obstruction is specific topology, not all circuits.',['30685624bf92','02848a53c8e7','322ce017f4bd','ccdba45f70f7','3b3b0db72f07','8eea380202a2'],['https://arxiv.org/abs/2211.04643','https://arxiv.org/abs/2211.06459'])
add(75,'Thin rectangular multiplication source and compiler gate','A cited thin-matrix theorem cannot be substituted as a free fully specified FFT compiler.','Brockett–Dobkin orientation is n×n times n×log n; 1978 correction changes two signs. Original constructive 1976 text not obtained in saved access pass; later support for total arithmetic exists but nonscalar-multiplication excerpt alone is insufficient.','Any use must charge additions, coefficient preparation, transpositions, rectangular dimensions and output; explicit uniform compiler not recovered.','Conditional algebraic circuit citation; primary construction scope unresolved.','Source-access boundary, unranked; no negative theorem inferred from missing text.','Known external matrix multiplication result, not ours.','1978 errata fully read historically; 1976 construction and thesis remain access gaps. Do not invent exact addition circuit or rule out result.',['ca5d82292b10'],['https://epubs.siam.org/doi/10.1137/0205041','https://epubs.siam.org/doi/10.1137/0207021'])
add(76,'Frequency-shift sketches, nonlinear median and energy adaptation','Earlier approximate branches have exact variance tradeoffs and a sharp rank-model comparison.','N=KM one unbiased row costs O(Nlog M+Klog K+N), per-bin variance (M−1)||x||²/N. For any unbiased random input-independent rank<=k linear estimator of a unitary, worst-direction expected full squared error >=N/k−1; this row attains equality at k=K.','Independent-row coordinate medians paid; balanced buckets trade collision factor against extra long transforms.','Ideal complex arithmetic and explicitly independent random states; nonlinear median outside linear minimax proof.','Accepted variance/minimax and scoped measurement barrier; earlier approximate precursor.','Random sketch/linear rank methods known; useful exact comparison.','Deficient fixed linear measurements cannot recover all continuous inputs; stronger almost-everywhere inputwise statement needs measurability. Does not apply to input-adaptive raw reads or finite discrete sets.',['4cab10dbc7da','2a29e1c3fdd9','0e029e7ee61a'])
add(77,'All-length Chebyshev/Bessel and rational-Taylor lifts','Streaming avoids rank-times-array storage but leaves the expansion decoder work and precision assumptions.','Exact Clenshaw/Neumann fusion identities; H=0 center error <=(tau_R+Delta)||x||2, Delta=pi(M−1)/Q, variance <=(M/N)(1+tau_R)²||x||². Negative channels redundant; summary-only exact recovery requires L(H+1)>=M.','O(RN) decoder scans and O(N) storage for fixed H; charged rational-Taylor variant removes Bessel oracle but not R passes.','Approximate ideal arithmetic; finite precision conditional on decoder-on-summaries contract, summable coefficient envelope and paid coefficient generator.','Independent audit supports exact identities and repairs conditional error contract; not NumPy/SciPy certification.','Classical Chebyshev/Clenshaw/Bessel identities applied to this decoder.','Original full-row error contract insufficient for separately rounded summaries. Higher expansion rank does not evade information rank. All-length padded outputs require correct interpolation and normalization.',['29d7a474e8cc','cc5266d257e7','ef1423c115d5','f1b00ce0bbf8','ff2d534976d8'],['https://dlmf.nist.gov/10.23.E2','https://dlmf.nist.gov/10.12','https://dlmf.nist.gov/10.9.E1'])
add(78,'Joint universal-orbit and compiled q-grid application','Joint recovery avoids an unnecessary quadratic-size executor, but composing it still gives ordinary FFT order.','Square orbit coefficient recovery uses two geometric-Vandermonde convolutions with O(N) shared preparation; full joint synthesis O(Nlog N). M-step q-product has scalar-denominator recurrence; raw kernels P_M,D prepared O(N) with cyclic solves and one shared inversion.','Literal M factors cost Theta(MN); compiled 2D application Theta(Nlog N), 3Nlog2 M+2N butterflies before pointwise work. Extra smooth convolution root explicitly supplied.',field,'Independent reviews accept identities, linear preparation improvement and application accounting.','Classical q-binomial/Vandermonde convolution synthesis.','Input kernel identity is not a free arbitrary-input solve: a(z)/a(eta z) may not exist, and a(z)=z counterexample. Grid zero multipliers save only O(M) products; common-anchor/growing-radix exclusions remain interface-specific. Exponential orbit conditioning affects finite precision.',['e8e4702ce798','a0de94c56ca7','c246caae9a32','2222b39b1ce5','49eea4a5eb25','47361092ab32'],qref)
add(79,'Deferred butterflies, probes and mixed-radix fallback','Reuse preview work on rejected inputs instead of recomputing the same butterflies.','Deferred DIF returns selected probes then completes exact radix-two FFT without repeated butterfly arithmetic; Green-conjugated probe and fixed-batch backup counts valid. Good–Thomas mixed-radix uses classical coprime split.','All detector/setup/root/backup work paid; accepted structured branch may save locally but all 12 historical benchmarks exceed native radix-two baseline.','Exact supplied compatible field/root plus stricter Green diagonal and closure guards.','Independent audit accepts scheduling mathematics, reports concrete API/domain defects.','Known pruning/deferred computation engineering; no asymptotic novelty.','Green constructor can reject invertible N16/GF17 due zero diagonal. Calling full then preview produces wrong DC unless guard repaired; intended preview then full valid. Generic input gets detector overhead.',['ad2605864836','1da0c9080dcd','2024b0f78347','c59cd20da8cd','a9e80e396765'],['https://fftw.org/pruned.html'])
add(80,'High-arity and nonunitary gate tolls','Larger or nonunitary gates do not become free scalar operations.','In-place complex unitary gates require sum b_g log2 b_g>=Nlog2 N; bounded-entry invertible gates obey N/2 ln N<=sum b_g(ln C+0.5 ln b_g). Field split-radix and radix2 have identical A=Nlog2N,M=(N/2)log2N−N+1 under paid i-multiplication; displayed shear lift adds (N/2)log2N operations.','Charge actual local gate expansion; finite field constants and root setup separate from complex entropy/volume.','Complex no-extra-workspace unitary or bounded-entry model; exact field finite circuit counts separately.','Independent audit accepts scoped classical tolls and field counts.','Explicit forms of known Ailon/Morgenstern methods; unranked.','No finite-field transfer of magnitude lower bounds, no unrestricted arithmetic lower bound, no reason arbitrary growing-arity Fourier gate costs one scalar operation.',['e202748f566a','452abe0aa037'],['https://arxiv.org/abs/1305.4745'])
add(81,'Original aggregate-fiber linear theorem','Bound total intermediate modes rather than every individual fiber.','N=QM, total fiber modes<=K0: complete exact raw recognition/rejection and full DFT O(N+MK0+QK0+K0²); K0=O(Q),Q²<=N gives O(N).','Capped BM, root scan, full verification and heavy M² fallbacks all charged, including final rejected fallback; O(N) roots/output.','Exact supplied-root field, characteristic not dividing N.','Independent audit accepts all-input recognition cost and accepted-class output.','Classical sparse recovery with precise budget accounting; supporting parameter regime.','No generic dense-input speedup; growing-budget theorem in ALG-002 is separate, not uniformly better. Full input read contract requires explicit scan before early rejection.',['eaabc7dbe9c2','74ac28217770'],prony)
